    ('Hamburger Box', 'Packaging', 'each', 'Pack', 25, 2.600000),
    ('Spaghetti Lunch Box', 'Packaging', 'each', 'Pack', 25, 2.400000)
),
loc as (
  select id from public.pos_locations
  where company_id = '11111111-2222-4333-8444-555555555555' and lower(name) = lower('Main Store')
  limit 1
)
insert into public.pos_items
  (company_id, location_id, name, category, item_type, base_unit, purchase_unit,
   pack_size, standard_unit_cost)
select
  '11111111-2222-4333-8444-555555555555',
  (select id from loc),
  s.name,
  s.category,
  'raw_material',
  s.base_unit::public.pos_base_unit,
  s.purchase_unit,
  s.pack_size,
  s.standard_unit_cost
from seed s
on conflict (company_id, lower(name))
do update set
  category           = excluded.category,
  base_unit          = excluded.base_unit,
  purchase_unit      = excluded.purchase_unit,
  pack_size          = excluded.pack_size,
  standard_unit_cost = excluded.standard_unit_cost,
  updated_at         = now();


-- --- prep items (sub-assemblies) ---------------------------------------------

with seed (name, category, base_unit, purchase_unit, pack_size, prep_yield_qty) as (
  values
    ('Espresso', 'Prep', 'ml', 'Batch', 36, 36),
    ('Cheesecake', 'Prep', 'each', 'Batch', 12, 12),
    ('Mango Float', 'Prep', 'each', 'Batch', 15, 15)
)
insert into public.pos_items
  (company_id, location_id, name, category, item_type, base_unit, purchase_unit,
   pack_size, prep_yield_qty)
select
  '11111111-2222-4333-8444-555555555555',
  (select id from public.pos_locations where company_id = '11111111-2222-4333-8444-555555555555' order by created_at limit 1),
  s.name, s.category, 'sub_assembly', s.base_unit::public.pos_base_unit, s.purchase_unit,
  s.pack_size, s.prep_yield_qty
from seed s
on conflict (company_id, lower(name)) do update set
  category       = excluded.category,
  item_type      = excluded.item_type,
  base_unit      = excluded.base_unit,
  pack_size      = excluded.pack_size,
  prep_yield_qty = excluded.prep_yield_qty,
  updated_at     = now();

