select '11111111-2222-4333-8444-555555555555', s.name, s.category, s.product_type::public.pos_product_type
from seed s
on conflict (company_id, lower(name)) do update set
  category     = excluded.category,
  product_type = excluded.product_type,
  updated_at   = now();

