insert into public.pos_recipe_lines (company_id, owner_id, owner_type, item_id, qty)
select '11111111-2222-4333-8444-555555555555', v.id, 'variant', ing.id, s.qty
from seed s
join public.pos_products p
  on p.company_id = '11111111-2222-4333-8444-555555555555' and lower(p.name) = lower(s.product_name)
join public.pos_product_variants v
  on v.product_id = p.id and lower(v.size) = lower(s.size)
join public.pos_items ing
  on ing.company_id = '11111111-2222-4333-8444-555555555555' and lower(ing.name) = lower(s.item_name)
