-- --- recipe lines: modifiers -------------------------------------------------

with seed (product_name, group_name, modifier_name, item_name, qty) as (
  values
    ('Iced Latte', 'Add-ons', 'Extra shot', 'Espresso', 36),
    ('Iced Latte', 'Add-ons', 'Caramel drizzle', 'Caramel Sauce', 15),
    ('Iced Americano', 'Add-ons', 'Extra shot', 'Espresso', 36),
